create or replace function public.get_progression_challenges(p_limit integer default 25) returns jsonb language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; return coalesce((select jsonb_agg(to_jsonb(x) order by x.created_at desc) from (select id,code,name,description,challenge_type,target,reward_points,reward_badge_code,period,enabled,created_at,metrics_config from public.progression_challenges where enabled=true order by created_at desc limit least(greatest(coalesce(p_limit,25),1),100)) x),'[]'::jsonb); end $$;
revoke all on function public.get_progression_challenges(integer) from public,anon; grant execute on function public.get_progression_challenges(integer) to authenticated;

create or replace function public.get_my_progression_metric_summary() returns jsonb language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; return coalesce((select jsonb_agg(to_jsonb(x)) from (select metric,quantity,points_awarded,event_count,last_occurred_at from public.user_progression_metric_summary where user_id=auth.uid()) x),'[]'::jsonb); end $$;
revoke all on function public.get_my_progression_metric_summary() from public,anon; grant execute on function public.get_my_progression_metric_summary() to authenticated;

create or replace function public.get_my_progression_badges() returns jsonb language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; return coalesce((select jsonb_agg(jsonb_build_object('id',ub.badge_id,'earned_at',ub.earned_at,'badge',to_jsonb(b)) order by ub.earned_at desc) from public.user_badges ub join public.badges b on b.id=ub.badge_id where ub.user_id=auth.uid()),'[]'::jsonb); end $$;
revoke all on function public.get_my_progression_badges() from public,anon; grant execute on function public.get_my_progression_badges() to authenticated;

create or replace function public.get_my_progression_milestones() returns jsonb language plpgsql security definer set search_path=public,auth,extensions,pg_temp as $$ begin if auth.uid() is null then raise exception 'Authentication required'; end if; return coalesce((select jsonb_agg(to_jsonb(x) order by x.milestone_key) from (select milestone_key,achieved_at,points_awarded from public.contributor_milestones where user_id=auth.uid()) x),'[]'::jsonb); end $$;
revoke all on function public.get_my_progression_milestones() from public,anon; grant execute on function public.get_my_progression_milestones() to authenticated;
